function solve(precos) {
  const n = precos.length;
  if (n <= 1) return 0;

  // Max profit with at most 1 transaction up to day i (prefix)
  const prefix = new Array(n);
  let minPrice = precos[0];
  for (let i = 0; i < n; i++) {
    minPrice = Math.min(minPrice, precos[i]);
    prefix[i] = i > 0 ? Math.max(prefix[i - 1], precos[i] - minPrice) : 0;
  }

  // Max profit with at most 1 transaction from day i to the end (suffix)
  const suffix = new Array(n);
  let maxPrice = precos[n - 1];
  for (let i = n - 1; i >= 0; i--) {
    maxPrice = Math.max(maxPrice, precos[i]);
    suffix[i] = i < n - 1 ? Math.max(suffix[i + 1], maxPrice - precos[i]) : 0;
  }

  // Best split: sell in the first part, buy again in the second part
  let maxProfit = 0;
  for (let i = 0; i < n; i++) {
    maxProfit = Math.max(maxProfit, prefix[i] + suffix[i]);
  }

  return maxProfit;
}
